#!/usr/bin/env bash
set -euo pipefail

# check_tree_sitter_generated.sh
# Drift check for the generated tree-sitter sources of rholang-tree-sitter.
#
# 1. Regenerates the parser from grammar.js into a scratch copy with
#    tree-sitter-cli 0.25.10, and compares src/grammar.json,
#    src/node-types.json, src/parser.c and src/tree_sitter/*.h byte for byte
#    with the files in the tree. The generated files are never edited by hand.
# 2. Derives the three exclusion tables of the external scanner from the
#    baseline grammar (02cef80 unless given), checks the lookahead rule with
#    scripts/derive_scanner_exclusions.js, and checks that the tables
#    USE_EXCLUDED_WORDS, FREE_EXCLUDED_WORDS and QUOTE_EXCLUDED_WORDS in
#    src/scanner.c are exactly the derived ones.
#
# Usage:
#   TREE_SITTER_BIN=/path/to/tree-sitter ./scripts/check_tree_sitter_generated.sh [--self-test] [BASELINE]
#
# TREE_SITTER_BIN defaults to `tree-sitter` on PATH; it must report version
# 0.25.10 (another version generates a different parser.c). `node` must be on
# PATH: `tree-sitter generate` evaluates grammar.js with it.
#
# --self-test also runs negative controls: a changed generated file and a
# changed scanner table must each be detected.
# Scratch files go under target/tmp (never /tmp).

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")"/.. && pwd)"
GRAMMAR_DIR="$ROOT_DIR/rholang-tree-sitter"
TREE_SITTER_BIN=${TREE_SITTER_BIN:-tree-sitter}
REQUIRED_VERSION=0.25.10
GENERATED_FILES=(
  src/grammar.json
  src/node-types.json
  src/parser.c
  src/tree_sitter/parser.h
  src/tree_sitter/alloc.h
  src/tree_sitter/array.h
)

SELF_TEST=false
if [[ "${1:-}" == "--self-test" ]]; then
  SELF_TEST=true
  shift
fi
BASELINE=${1:-02cef80}

version="$("$TREE_SITTER_BIN" --version 2> /dev/null | awk '{ print $2 }')"
if [[ "$version" != "$REQUIRED_VERSION" ]]; then
  echo "[error] $TREE_SITTER_BIN reports version '${version:-none}', need $REQUIRED_VERSION" >&2
  exit 2
fi
command -v node > /dev/null || { echo "[error] node is not on PATH" >&2; exit 2; }

mkdir -p "$ROOT_DIR/target/tmp"
SCRATCH="$(mktemp -d "$ROOT_DIR/target/tmp/ts-drift.XXXXXX")"
trap 'rm -rf "$SCRATCH"' EXIT
export TMPDIR="$SCRATCH"

# Regenerate from grammar.js. tree-sitter.json and package.json are copied
# because the generator reads the grammar metadata from them.
regenerated="$SCRATCH/regenerated"
mkdir -p "$regenerated"
cp "$GRAMMAR_DIR/grammar.js" "$GRAMMAR_DIR/tree-sitter.json" "$GRAMMAR_DIR/package.json" "$regenerated/"
(cd "$regenerated" && "$TREE_SITTER_BIN" generate > "$SCRATCH/generate.log" 2>&1) || {
  cat "$SCRATCH/generate.log" >&2
  echo "[error] tree-sitter generate failed" >&2
  exit 1
}

# compare_generated TREE_DIR: compares the generated files of TREE_DIR with
# the regenerated ones; returns 1 on drift.
compare_generated() {
  local tree=$1 drift=0 file
  for file in "${GENERATED_FILES[@]}"; do
    if cmp -s "$regenerated/$file" "$tree/$file"; then
      echo "ok    $file"
    else
      echo "DRIFT $file differs from the output of tree-sitter $REQUIRED_VERSION generate"
      drift=1
    fi
  done
  if ! head -1 "$tree/src/parser.c" | grep -q "tree-sitter v$REQUIRED_VERSION"; then
    echo "DRIFT src/parser.c was not generated by tree-sitter v$REQUIRED_VERSION"
    drift=1
  fi
  return $drift
}

# The words of one exclusion table of a scanner.c, one per line, sorted.
scanner_words() {
  awk -v table="$2" '$0 ~ table "\\[\\] = \\{" { inside = 1; next } inside && /^\};/ { exit } inside' "$1" \
    | grep -o '"[^"]*"' | tr -d '"' | sort
}

# The words of one derived table (`use`, `free` or `quote`), sorted.
derived_words() {
  sed -n "s/^$1: //p" "$derived_log" | tr ' ' '\n' | grep -v '^$' | sort
}

# compare_exclusions SCANNER_C: compares the three tables with the derived
# ones; returns 1 when one differs.
derived_log="$SCRATCH/derived.log"
git -C "$ROOT_DIR" show "$BASELINE:rholang-tree-sitter/src/grammar.json" > "$SCRATCH/baseline-grammar.json"
derive_args=("$SCRATCH/baseline-grammar.json" "$GRAMMAR_DIR/src/grammar.json")
if $SELF_TEST; then
  derive_args=(--self-test "${derive_args[@]}")
fi
derive_status=0
node "$ROOT_DIR/scripts/derive_scanner_exclusions.js" "${derive_args[@]}" > "$derived_log" || derive_status=$?
compare_exclusions() {
  local scanner=$1 differs=0 form table
  for form in use free quote; do
    table="$(tr '[:lower:]' '[:upper:]' <<< "$form")_EXCLUDED_WORDS"
    if [[ -n "$(derived_words "$form")" && "$(scanner_words "$scanner" "$table")" == "$(derived_words "$form")" ]]; then
      echo "ok    src/scanner.c $table equals the $form table derived from $BASELINE"
    else
      echo "DRIFT src/scanner.c $table differs from the $form table derived from $BASELINE"
      diff <(scanner_words "$scanner" "$table") <(derived_words "$form") | sed 's/^/    /' || true
      differs=1
    fi
  done
  return $differs
}

echo "== generated sources ($TREE_SITTER_BIN $version)"
status=0
compare_generated "$GRAMMAR_DIR" || status=1
echo "== scanner keyword rule (baseline $BASELINE)"
sed 's/^/      /' "$derived_log"
(( derive_status == 0 )) || status=1
compare_exclusions "$GRAMMAR_DIR/src/scanner.c" || status=1

if $SELF_TEST; then
  echo "== self-test: negative controls"
  controls="$SCRATCH/controls"
  mkdir -p "$controls/src/tree_sitter"
  for file in "${GENERATED_FILES[@]}"; do
    cp "$GRAMMAR_DIR/$file" "$controls/$file"
  done
  printf '\n' >> "$controls/src/node-types.json"
  if compare_generated "$controls" > "$SCRATCH/control-generated.log"; then
    echo "self-test: FAIL (a changed generated file was not detected)"
    exit 1
  fi
  echo "self-test: changed generated file detected: $(grep -m1 DRIFT "$SCRATCH/control-generated.log")"
  sed 's/"bundle0", //' "$GRAMMAR_DIR/src/scanner.c" > "$controls/scanner.c"
  if compare_exclusions "$controls/scanner.c" > "$SCRATCH/control-scanner.log"; then
    echo "self-test: FAIL (a changed scanner table was not detected)"
    exit 1
  fi
  echo "self-test: changed scanner table detected: $(grep -m1 DRIFT "$SCRATCH/control-scanner.log")"
fi

if (( status != 0 )); then
  echo "tree-sitter drift check: FAIL"
  exit 1
fi
echo "tree-sitter drift check: PASS"
